/* Standalone GIF89a encoder. Local processing; no network dependencies. */
export function paletteFor(rgba, limit=256, fine=false){
 const hist=new Map(),step=fine?1:Math.max(1,Math.floor(rgba.length/4/50000));
 for(let i=0;i<rgba.length;i+=4*step){if(rgba[i+3]<128)continue;const key=(rgba[i]>>3)<<10|(rgba[i+1]>>3)<<5|(rgba[i+2]>>3);const p=hist.get(key);if(p){p[3]++}else hist.set(key,[(rgba[i]>>3)*8+4,(rgba[i+1]>>3)*8+4,(rgba[i+2]>>3)*8+4,1]);}
 let boxes=[Array.from(hist.values())];if(!boxes[0].length)return [[0,0,0],[255,255,255]];
 function metric(b){let lo=[255,255,255],hi=[0,0,0],n=0;for(const p of b){n+=p[3];for(let c=0;c<3;c++){lo[c]=Math.min(lo[c],p[c]);hi[c]=Math.max(hi[c],p[c]);}}const ranges=hi.map((x,c)=>x-lo[c]);const axis=ranges.indexOf(Math.max(...ranges));return {axis,score:ranges[axis]*Math.sqrt(n)}}
 while(boxes.length<limit-1){let index=-1,best=-1,axis=0;boxes.forEach((b,i)=>{if(b.length<2)return;const m=metric(b);if(m.score>best){best=m.score;index=i;axis=m.axis}});if(index<0)break;const box=boxes[index].sort((a,b)=>a[axis]-b[axis]);let total=box.reduce((s,p)=>s+p[3],0),sum=0,cut=1;for(;cut<box.length-1;cut++){sum+=box[cut-1][3];if(sum>=total/2)break}boxes.splice(index,1,box.slice(0,cut),box.slice(cut));}
 return [[0,0,0],...boxes.map(b=>{let n=0,c=[0,0,0];for(const p of b){n+=p[3];for(let k=0;k<3;k++)c[k]+=p[k]*p[3]}return c.map(v=>Math.round(v/n))})];
}
export function indexed(rgba,palette){const out=new Uint8Array(rgba.length/4),cache=new Map();for(let i=0,j=0;i<rgba.length;i+=4,j++){if(rgba[i+3]<128){out[j]=0;continue}const key=(rgba[i]>>3)<<10|(rgba[i+1]>>3)<<5|(rgba[i+2]>>3);let ix=cache.get(key);if(ix===undefined){let best=Infinity;ix=1;for(let k=1;k<palette.length;k++){const p=palette[k],d=(rgba[i]-p[0])**2+(rgba[i+1]-p[1])**2+(rgba[i+2]-p[2])**2;if(d<best){best=d;ix=k}}cache.set(key,ix)}out[j]=ix;}return out;}
function lzw(pixels){const clear=256,end=257;let next=258,bits=9,dict=new Map(),out=[],buffer=0,count=0;const emit=(code)=>{buffer|=code<<count;count+=bits;while(count>=8){out.push(buffer&255);buffer>>>=8;count-=8}};emit(clear);let prefix=pixels[0];for(let i=1;i<pixels.length;i++){const c=pixels[i],key=prefix*256+c,found=dict.get(key);if(found!==undefined){prefix=found;continue}emit(prefix);if(next<4096){if(next===(1<<bits)&&bits<12)bits++;dict.set(key,next++);}else{emit(clear);dict.clear();next=258;bits=9}prefix=c;}emit(prefix);if(next===(1<<bits)&&bits<12)bits++;emit(end);if(count)out.push(buffer&255);return out;}
export class Encoder{constructor(w,h,repeat=0){this.bytes=[];this.w=w;this.h=h;this.put(...Array.from('GIF89a',c=>c.charCodeAt(0)));this.word(w);this.word(h);this.put(0x70,0,0);if(repeat!==1){this.put(0x21,0xff,11,...Array.from('NETSCAPE2.0',c=>c.charCodeAt(0)),3,1);this.word(repeat===0?0:repeat-1);this.put(0)}}put(...v){this.bytes.push(...v)}word(v){this.put(v&255,(v>>8)&255)}frame(rgba,delay,colors=256,fine=false,transparent=false){let p=paletteFor(rgba,colors,fine),ix=indexed(rgba,p);this.put(0x21,0xf9,4,transparent?9:8);this.word(Math.max(2,Math.round(delay/10)));this.put(0,0,0x2c);this.word(0);this.word(0);this.word(this.w);this.word(this.h);this.put(0x87);for(let i=0;i<256;i++)this.put(...(p[i]||[0,0,0]));this.put(8);const data=lzw(ix);for(let i=0;i<data.length;i+=255){const block=data.slice(i,i+255);this.put(block.length,...block)}this.put(0)}finish(){this.put(0x3b);return new Uint8Array(this.bytes)}}
